function waivePlayer(p,from,{cpu=false}={}){
 if(currentTeam(p)!==from)return false;
 const years=contractYears(p).filter(y=>y.season_start>=state.seasonYear);
 state.assignments[p.id]=null;state.birdClock[p.id]=0;if(state.promises)delete state.promises[p.id];state.meetings=(state.meetings||[]).filter(m=>m.player_id!==p.id||m.status!=='pending');state.statusOverrides[p.id]='free_agent';
 state.deadCapLedger[from]=state.deadCapLedger[from]||{};let guaranteed=0;
 for(const y of years){if(!['player_option','team_option','early_termination'].includes(y.option)){state.deadCapLedger[from][y.season_start]=(state.deadCapLedger[from][y.season_start]||0)+y.amount;guaranteed+=y.amount}}
 state.freeAgentRights[p.id]={team:from,type:'UFA',level:'non_bird',last_salary:salaryOf(p),cap_hold:0,renounced:true};
 addTransaction('WAIVED',`${team(from).abbr} waived ${p.name}; ${money(guaranteed)} in modeled guaranteed salary remains on the cap across the remaining guaranteed years.`);if(!cpu)toast(`${p.name.toUpperCase()} WAIVED`);return true
}

function processContractsForNextSeason(oldYear){const next=oldYear+1,released=[];state.salaryOverrides={};for(const p of players){if(currentStatus(p)==='retired'||currentStatus(p)==='draft_prospect')continue;const tm=currentTeam(p);if(!tm)continue;const yrs=contractYears(p),yr=yrs.find(y=>y.season_start===next),cur=yrs.find(y=>y.season_start===oldYear)||{amount:salaryOf(p)},level=birdLevelFor(p);if(!yr){state.assignments[p.id]=null;state.statusOverrides[p.id]='free_agent';const type=(p.contract?.expiry==='RFA'||p.career_status?.includes('rookie'))?'RFA':'UFA',hold=Math.round(Math.max(cur.amount*1.5,marketAsk(p)*1.1));state.freeAgentRights[p.id]={team:tm,type,level,last_salary:cur.amount,cap_hold:hold,qualifying_offer:type==='RFA'?Math.max(p.contract?.qualifying_offer||0,Math.round(cur.amount*1.25)):0,renounced:false};released.push(p.name);continue}if(yr.option==='player_option'){const exercise=marketAsk(p)<=yr.amount*1.12||p.age>=34;if(!exercise){state.assignments[p.id]=null;state.statusOverrides[p.id]='free_agent';state.freeAgentRights[p.id]={team:tm,type:'UFA',level,last_salary:cur.amount,cap_hold:Math.round(cur.amount*1.5),renounced:false};released.push(p.name+' (declined player option)')}state.optionHistory.push({player_id:p.id,team:tm,year:next,type:'player_option',decision:exercise?'exercised':'declined'})}else if(yr.option==='team_option'){const keep=overall(p)>=69||yr.amount<marketAsk(p)*1.1;if(!keep){state.assignments[p.id]=null;state.statusOverrides[p.id]='free_agent';state.freeAgentRights[p.id]={team:tm,type:'UFA',level,last_salary:cur.amount,cap_hold:Math.round(cur.amount*1.5),renounced:false};released.push(p.name+' (team option declined)')}state.optionHistory.push({player_id:p.id,team:tm,year:next,type:'team_option',decision:keep?'exercised':'declined'})}}return released}
function beginOffseason(){const oldYear=state.seasonYear,champ=state.postseason?.champion;const records=Object.fromEntries(teams.map(t=>[t.abbr,record(t.abbr)]));state.history.push({season:oldYear,champion:champ,finalsMvp:state.postseason?.finalsMvp||null,finals:state.postseason?.finals?structuredClone(state.postseason.finals):null,awards:structuredClone(state.awards),records});const lottery=buildDraftOrder(records);const retirements=[],development=[];for(const p of players){if(currentStatus(p)==='retired'||currentStatus(p)==='draft_prospect')continue;const dev=applyDevelopment(p);development.push({id:p.id,...dev});let chance=retirementChance(p);if(overall(p)<68&&p.age>=35)chance+=.12;if(rng()<chance){const tm=currentTeam(p);state.assignments[p.id]=null;state.statusOverrides[p.id]='retired';retirements.push({id:p.id,name:p.name,team:tm,age:p.age});state.retired.push(p.id);addTransaction('RETIRED',`${p.name} retired at age ${p.age}.`,`${oldYear+1}-06-01`)}}const released=processContractsForNextSeason(oldYear);state.exceptionHistory[oldYear]=structuredClone(state.exceptionUsage||{});state.deadCap={};state.otherCap=Object.fromEntries(teams.map(t=>[t.abbr,0]));state.seasonYear=oldYear+1;state.exceptionUsage={};state.hardCaps={};ensureFuturePickHorizon();state.seasonStarted=false;state.seasonComplete=false;state.results={};state.seasonStats={};state.postseason=null;state.awards=null;state.phase='draft';state.freeAgency=null;state.date=`${state.seasonYear}-06-20`;processMedicalDay(state.date);state.offseasonSummary={retirements,development:development.sort((a,b)=>b.delta-a.delta),released};state.draft=lottery;generateDraftClass();refreshSeasonConfig();persist();renderView();setTop();toast('OFFSEASON BEGINS')}
function signDraftPick(p,teamAbbr,pick){state.assignments[p.id]=teamAbbr;state.statusOverrides[p.id]='active';p.roster_status='active';const salary=rookieSalaryForPick(pick);const rows=Array.from({length:4},(_,i)=>({season_start:state.seasonYear+i,season:`${state.seasonYear+i}-${String((state.seasonYear+i+1)%100).padStart(2,'0')}`,amount:Math.round(salary*Math.pow(1.045,i)),option:i<2?'guaranteed':'team_option',source:'rookie_scale'}));state.contractOverrides[p.id]={years:rows,expiry:'RFA',signed:state.date,route:'rookie_scale',team:teamAbbr};p.contract.years=rows;p.draft_projection={...(p.draft_projection||{}),rookieSeason:state.seasonYear};state.teamTenure[p.id]=1;state.birdClock[p.id]=0;state.draft.selections.push({pick,team:teamAbbr,origin:state.draft.originOrder?.[pick-1]||teamAbbr,player_id:p.id});addTransaction('DRAFT',`${team(teamAbbr).abbr} selected ${p.name} with pick No. ${pick}.`,state.date);state.draft.pickIndex++}
function startNextSeason(){ensureFuturePickHorizon();if(state.phase==='free_agency'&&!faEnsure()?.complete){toast('COMPLETE FREE AGENCY FIRST');return}if(Object.values(state.freeAgency?.rfaMatches||{}).some(m=>m.status==='pending'&&m.rights_team===userTeam)){currentView='market';renderView();toast('RFA MATCH DECISION REQUIRED');return}if(signedCount(userTeam)>15)return;autoTrimCpu();autoFillCpu();ensureAllRotations();state.seasonStarted=true;state.seasonComplete=false;state.phase='regular_season';state.date=DATES.opening_day;processMedicalDay(state.date);state.results={};state.seasonStats={};state.gameLogs={};state.postseason=null;state.postseasonResults={};state.playoffStats={};state.playoffGameLogs={};state.awards=null;state.draft=null;state.offseasonSummary=null;for(const p of players)if(currentTeam(p)){state.teamTenure[p.id]=Math.min(3,(state.teamTenure[p.id]||0)+1);state.birdClock[p.id]=Math.min(3,(state.birdClock[p.id]||0)+1)};updateMoraleAll(state.date,true);persist();renderView();setTop();toast(`${CAP.season} SEASON STARTED`)}
function tradeView(){if(!tradePartner||tradePartner===userTeam)tradePartner=teams.find(t=>t.abbr!==userTeam).abbr;const ut=team(userTeam),pt=team(tradePartner),mine=teamPlayers(userTeam,{activeOnly:true}).sort((a,b)=>overall(b)-overall(a)),theirs=teamPlayers(tradePartner,{activeOnly:true}).sort((a,b)=>overall(b)-overall(a));if(!tradeOpen())return `<div class="sectionHead"><h2>Trade Center</h2><span>LOCKED</span></div><div class="deadlineLock"><b>TRADES LOCKED</b><span>Trades are unavailable during the postseason and after the in-season deadline.</span></div>`;const uc=capStatus(capHit(userTeam)),cc=capStatus(capHit(tradePartner));return `<div class="sectionHead"><h2>Trade Center</h2><span>${state.seasonStarted?`${shortDate(DATES.trade_deadline)} DEADLINE`:'OFFSEASON'}</span></div><div class="cbaTradeBands"><div><span>${userTeam}</span><b>${uc}</b></div><div><span>${tradePartner}</span><b>${cc}</b></div></div><div class="partnerStrip">${teams.filter(t=>t.abbr!==userTeam).map(t=>`<button class="partner ${t.abbr===tradePartner?'active':''}" data-partner="${t.abbr}">${logo(t)}</button>`).join('')}</div>${frontOfficePanel(tradePartner)}${offerSide(ut,mine,tradeMine,'mine')}${offerSide(pt,theirs,tradeTheirs,'theirs')}<div id="tradeCalc">${tradeSummary()}</div><button class="propose" id="proposeTrade">RUN CBA CHECK + PROPOSE</button><div class="response hidden" id="tradeResponse"></div><div class="notice good" style="margin-top:10px"><strong>2023 CBA trade engine:</strong> cap-room, tax, first-apron and second-apron matching bands are enforced; second-apron salary aggregation is blocked.</div>`}


