function ensureDraftExperience(){
 if(!state.draft)return null;
 const ids=state.draft.prospectIds||[];
 if(!state.draftExperience||state.draftExperience.year!==state.seasonYear){
  state.draftExperience={year:state.seasonYear,stage:state.phase==='draft'?'draft':'lottery',lotteryReveal:0,scoutingPoints:18,reports:{},board:[...ids],targets:[],tradeOffers:[],tradeHistory:[],lastSelection:null,lotteryComplete:false,scoutingComplete:false,draftStarted:false};
 }
 const dx=state.draftExperience;
 dx.reports=dx.reports||{};dx.board=dx.board?.length?dx.board.filter(id=>ids.includes(id)):[...ids];
 for(const id of ids)if(!dx.board.includes(id))dx.board.push(id);
 dx.targets=dx.targets||[];dx.tradeOffers=dx.tradeOffers||[];dx.tradeHistory=dx.tradeHistory||[];
 return dx;
}
function dateState(){if(state.phase==='lottery')return'DRAFT LOTTERY';if(state.phase==='scouting')return'PRE-DRAFT';if(state.phase==='draft')return'NBA DRAFT';if(state.phase==='training_camp')return'TRAINING CAMP';if(state.phase==='free_agency')return'FREE AGENCY';if(state.phase==='playin')return'PLAY-IN';if(state.phase==='playoffs')return'PLAYOFFS';if(state.phase==='champion')return'NBA CHAMPION';if(state.phase==='offseason')return state.seasonStarted?'OFFSEASON':'PRESEASON';if(!state.seasonStarted)return'OFFSEASON';if(state.seasonComplete)return'REGULAR SEASON COMPLETE';if(state.date>DATES.trade_deadline)return'POST-DEADLINE';return'REGULAR SEASON'}
function tradeOpen(){return ['offseason','lottery','scouting','draft','free_agency','training_camp','regular_season'].includes(state.phase)&&!state.seasonComplete&&(!state.seasonStarted||state.date<=DATES.trade_deadline)}
function faEnsure(){if(state.freeAgency?.year===state.seasonYear)return state.freeAgency;const eligible=state.phase==='free_agency'||state.phase==='training_camp'||(state.phase==='offseason'&&!state.seasonStarted);if(!eligible)return null;return startFreeAgencyPeriod()}
