function lotteryRevealNext(){const dx=ensureDraftExperience();if(!dx)return;dx.lotteryReveal=Math.min(16,(dx.lotteryReveal||0)+1);if(dx.lotteryReveal>=16){dx.lotteryComplete=true;toast('LOTTERY ORDER SET')}persist();renderView()}
