function lotteryView(){const dx=ensureDraftExperience(),lot=state.draft.lotteryOrder||[],revealed=new Set();for(let i=0;i<dx.lotteryReveal;i++)revealed.add(16-i);const owned=state.draft.order.slice(0,16).map((a,i)=>a===userTeam?i+1:null).filter(Boolean),ownOrigin=state.draft.originOrder.slice(0,16).map((a,i)=>a===userTeam?i+1:null).filter(Boolean);return `${hero()}<section class="lotteryHero"><span>${state.seasonYear} NBA DRAFT LOTTERY</span><h2>LOTTERY<br>NIGHT.</h2><small>16 TEAMS · THE 3-2-1 ERA</small></section><div class="lotteryYour"><span>YOUR DRAFT POSITION</span><b>${owned.length?owned.map(x=>'#'+x).join(' · '):'NO LOTTERY PICK'}</b><small>${ownOrigin.length?`Your original slot${ownOrigin.length>1?'s':''}: ${ownOrigin.map(x=>'#'+x).join(' · ')}`:'Your draft capital comes through traded assets.'}</small></div><div class="sectionHead"><h2>Reveal Board</h2><span>${dx.lotteryReveal}/16 REVEALED</span></div><div class="lotteryBoard">${Array.from({length:16},(_,j)=>16-j).map(slot=>{const origin=lot[slot-1],owner=state.draft.order[slot-1],show=revealed.has(slot);return `<div class="lotterySlot ${show?'revealed':'hiddenPick'} ${owner===userTeam?'yours':''}"><b>${slot}</b>${show?logo(team(origin)):'<i>?</i>'}<div><strong>${show?team(origin).name:'PICK HIDDEN'}</strong><span>${show&&owner!==origin?`PICK OWNED BY ${owner}`:show?'OWN PICK':'REVEAL FROM 16 → 1'}</span></div></div>`}).join('')}</div>${!dx.lotteryComplete?`<div class="lotteryActions"><button id="revealLotteryNext">REVEAL NEXT PICK</button><button id="revealLotteryAll">REVEAL ALL</button></div>`:`<button class="primaryAction" id="enterScouting">ENTER SCOUTING HUB</button>`}<div class="notice" style="margin-top:10px"><strong>Draft rights matter.</strong> The lottery establishes original slots, then pick protections, swaps and traded ownership determine which franchise is actually on the clock.</div>`}
